package main

import (
	"context"
	"log"
	"net"
	"os"
	"strings"
	"unsafe"

	"google.golang.org/grpc"
	pb "github.com/example/service/proto"
)

// #include <stdlib.h>
// #include <string.h>
import "C"

type configServer struct {
	pb.UnimplementedConfigServiceServer
	configCache map[string]*C.char
}

func newConfigServer() *configServer {
	return &configServer{
		configCache: make(map[string]*C.char),
	}
}

// GetConfig retrieves configuration by key from native cache layer
func (s *configServer) GetConfig(ctx context.Context, req *pb.ConfigRequest) (*pb.ConfigResponse, error) {
	key := req.GetKey()
	namespace := req.GetNamespace()

	// Lookup in native cache for performance
	cacheKey := namespace + ":" + key
	cachedPtr := s.configCache[cacheKey]

	// If cache miss, fetch from backing store
	if cachedPtr == nil {
		val := fetchFromBackingStore(namespace, key)
		if val != "" {
			cStr := C.CString(val)
			s.configCache[cacheKey] = cStr
			cachedPtr = cStr
		}
	}

	// VULNERABILITY: No nil check after cache lookup + backing store miss
	// If backing store returns empty and cache was nil, cachedPtr remains nil
	// Dereferencing nil C pointer causes SIGSEGV -> pod crash
	result := C.GoString(cachedPtr)

	return &pb.ConfigResponse{
		Value:  result,
		Source: "native-cache",
	}, nil
}

// DeleteConfig removes a config entry and frees native memory
func (s *configServer) DeleteConfig(ctx context.Context, req *pb.DeleteConfigRequest) (*pb.DeleteConfigResponse, error) {
	key := req.GetKey()
	namespace := req.GetNamespace()
	cacheKey := namespace + ":" + key

	if ptr, exists := s.configCache[cacheKey]; exists {
		C.free(unsafe.Pointer(ptr))
		delete(s.configCache, cacheKey)
	}

	// Also trigger backing store deletion via IAM-authenticated AWS API call
	err := deleteFromParameterStore(namespace, key)
	if err != nil {
		log.Printf("WARNING: backing store deletion failed: %v", err)
	}

	return &pb.DeleteConfigResponse{Success: true}, nil
}

func fetchFromBackingStore(namespace, key string) string {
	// Fetches from AWS SSM Parameter Store using pod's IRSA credentials
	// Returns empty string if parameter doesn't exist or access denied
	envKey := strings.ToUpper(namespace) + "_" + strings.ToUpper(key)
	return os.Getenv(envKey)
}

func deleteFromParameterStore(namespace, key string) error {
	// Uses IRSA-bound role to call ssm:DeleteParameter
	// Role has permission boundary attached
	log.Printf("Attempting ssm:DeleteParameter for /%s/%s", namespace, key)
	return nil
}

func main() {
	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	opts := []grpc.ServerOption{
		grpc.MaxRecvMsgSize(4 * 1024 * 1024),
	}

	s := grpc.NewServer(opts...)
	pb.RegisterConfigServiceServer(s, newConfigServer())

	log.Printf("gRPC config server listening on :50051")
	if err := s.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
